package io.imiocode.team.tool;
import com.fasterxml.jackson.databind.node.ObjectNode;import io.imiocode.team.model.TeamPrincipal;import io.imiocode.team.task.*;import io.imiocode.tool.*;import java.util.function.Supplier;
public final class TaskUpdateTool extends AbstractTaskTool {public TaskUpdateTool(TeamTaskService t,Supplier<TeamPrincipal> p,ToolLimits l,SecretRedactor r){super(def(),t,p,l,r);}private static ToolDefinition def(){ObjectNode s=schema();var p=s.withObject("properties");p.putObject("task_id").put("type","string");p.putObject("status").put("type","string");p.putObject("assignee").put("type","string");p.putObject("result").put("type","string");p.putObject("addBlocksOn").put("type","string");p.putObject("addBlockedBy").put("type","string");p.putObject("expected_version").put("type","integer").put("minimum",1);s.putArray("required").add("task_id");return new ToolDefinition("TaskUpdate","更新团队任务状态、负责人和双向依赖。",s,ToolRisk.LOW);}@Override protected ToolResult executeValidated(ObjectNode a){rejectUnknownFields(a,"task_id","status","assignee","result","addBlocksOn","addBlockedBy","expected_version");TeamTaskStatus status=a.path("status").asText("").isBlank()?null:TeamTaskStatus.valueOf(a.path("status").asText());Long version=a.has("expected_version")?a.path("expected_version").asLong():null;return json(tasks.update(principal(),requireText(a,"task_id"),status,a.has("assignee")?a.path("assignee").asText():null,a.has("result")?a.path("result").asText():null,a.path("addBlocksOn").asText(""),a.path("addBlockedBy").asText(""),version));}}
